    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -1 }],
  }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects discountPercent above 100', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 101 }],
  }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects non-numeric discountPercent', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
  }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice accepts decimal discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('addLine accepts discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const newInvoice = addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: 15 });
  assert.equal(newInvoice.ok, true);
  assert.equal(newInvoice.value.lines[1].discountPercent, 15);
});

test('addLine rejects invalid discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: 150 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
});

test('createInvoice applies gold tier discount (5%) when not specified', () => {
  // C-001 is Northwind Studio with gold tier
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount (2.5%) when not specified', () => {
  // C-003 is Kite & Co with silver tier
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0%) when not specified', () => {
  // C-002 is Blue Fern Bakery with standard tier
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discountPercent overrides tier discount', () => {
  // C-001 is gold tier (5%), but explicit 10% should override
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice explicit discountPercent of 0 overrides tier discount', () => {
  // C-001 is gold tier (5%), but explicit 0% should override
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice applies tier discount to multiple lines', () => {
  // C-003 is silver tier (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 2.5);
});

test('createInvoice mixed tier and explicit discounts', () => {
  // C-001 is gold tier (5%)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // Should get tier discount
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 8 }, // Explicit discount
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
  assert.equal(result.value.lines[1].discountPercent, 8);
});

test('invoiceTotals with tier discount applied', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 5 }, // 42500 * 5 / 100 = 2125
      { qty: 10, unitPrice: 9500, discountPercent: 5 }, // 95000 * 5 / 100 = 4750
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal = 42500 + 95000 = 137500
  // Discount = 2125 + 4750 = 6875
  // Total = 137500 - 6875 = 130625
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 6875);
  assert.equal(totals.total, 130625);
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const newInvoice = addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(newInvoice.ok, true);
  assert.equal(newInvoice.value.lines.length, 2);
  assert.equal(newInvoice.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(newInvoice.value.lines[1].qty, 10);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const newInvoice = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(newInvoice.ok, true);
  assert.equal(newInvoice.value.lines.length, 1);
  assert.equal(newInvoice.value.lines[0].qty, 8);
});

test('addLine validates qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 2.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine validates SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result.value, { sku: 'NOPE', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate the original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const original = JSON.stringify(result.value);
  addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(JSON.stringify(result.value), original);
});

test('removeLine removes a line from an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  const newInvoice = removeLine(result.value, 'DES-HOUR');
  assert.equal(newInvoice.ok, true);
  assert.equal(newInvoice.value.lines.length, 1);
  assert.equal(newInvoice.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for missing SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(removeLine(result.value, 'NOPE'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine refuses to remove the last line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(removeLine(result.value, 'DES-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate the original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  const original = JSON.stringify(result.value);
  removeLine(result.value, 'DES-HOUR');
  assert.equal(JSON.stringify(result.value), original);
});

test('issueInvoice assigns a number and changes status', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.number, 'INV-2026-0001');
  assert.equal(issued.value.status, 'issued');
});

test('issueInvoice assigns next available number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(result.value, ['INV-2026-0001', 'INV-2026-0002']);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.number, 'INV-2026-0003');
});

test('issueInvoice respects year boundaries for numbering', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-05-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(result.value, ['INV-2026-0001', 'INV-2026-9999']);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.number, 'INV-2027-0001');
});

test('issueInvoice refuses to issue non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice preserves all invoice data', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  const issued = issueInvoice(result.value, []);
  assert.equal(issued.value.customerId, 'C-003');
  assert.equal(issued.value.issueDate, '2026-10-07');
  assert.equal(issued.value.lines.length, 2);
  assert.equal(issued.value.lines[0].sku, 'DES-HOUR');
});

test('issueInvoice does not mutate the original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const original = JSON.stringify(result.value);
  issueInvoice(result.value, []);
  assert.equal(JSON.stringify(result.value), original);
});

